125:     assert(parser->data_len >= 0);
126:     assert(parser->data_len <= MAX_PACKET_SIZE);
127:     assert(parser->data_read >= 0);
128:     assert(parser->data_read <= parser->data_len);
129:     assert((parser->data_len != 0) ^ (parser->data == NULL));
130: 
131:     int write_buf_count = 0;
132:     uint64_t total_size = 0;
133:     const struct usbredirparser_buf *write_buf = parser->write_buf;
134:     for (; write_buf != NULL ; write_buf = write_buf->next) {
135:         assert(write_buf->pos >= 0);
136:         assert(write_buf->len >= 0);
137:         assert(write_buf->pos <= write_buf->len);
138:         assert(write_buf->len == 0 || write_buf->buf != NULL);
139:         write_buf_count++;
