320: static void usbredirparser_handle_hello(struct usbredirparser *parser_pub,
321:     struct usb_redir_hello_header *hello, uint8_t *data, int data_len)
322: {
323:     struct usbredirparser_priv *parser =
324:         (struct usbredirparser_priv *)parser_pub;
325:     uint32_t *peer_caps = (uint32_t *)data;
326:     char buf[64];
327:     int i;
328: 
329:     if (parser->have_peer_caps) {
330:         ERROR("Received second hello message, ignoring");
331:         return;
332:     }
333: 
334:     /* In case hello->version is not 0 terminated (which would be a protocol
335:        violation)_ */
336:     strncpy(buf, hello->version, sizeof(buf));
337:     buf[sizeof(buf)-1] = '\0';
338: 
339:     memset(parser->peer_caps, 0, sizeof(parser->peer_caps));
340:     if (data_len > sizeof(parser->peer_caps)) {
341:         data_len = sizeof(parser->peer_caps);
342:     }
343:     for (i = 0; i < data_len / sizeof(uint32_t); i++) {
344:         parser->peer_caps[i] = peer_caps[i];
345:     }
346:     usbredirparser_verify_caps(parser, parser->peer_caps, "peer");
347:     parser->have_peer_caps = 1;
348: 
349:     INFO("Peer version: %s, using %d-bits ids", buf,
350:          usbredirparser_using_32bits_ids(parser_pub) ? 32 : 64);
351: 
352:     /* Added in 0.3.2, so no guarantee it is there */
353:     if (parser->callb.hello_func)
354:         parser->callb.hello_func(parser->callb.priv, hello);
355: }
