515:     case usb_redir_bulk_streams_status:
516:         if (!command_for_host) {
517:             return sizeof(struct usb_redir_bulk_streams_status_header);
518:         } else {
519:             return -1;
520:         }
521:     case usb_redir_cancel_data_packet:
522:         if (command_for_host) {
523:             return 0; /* No packet type specific header */
524:         } else {
525:             return -1;
526:         }
527:     case usb_redir_filter_reject:
528:         if (command_for_host) {
529:             return 0;
530:         } else {
531:             return -1;
532:         }
533:     case usb_redir_filter_filter:
534:         return 0;
535:     case usb_redir_device_disconnect_ack:
536:         if (command_for_host) {
537:             return 0;
538:         } else {
539:             return -1;
540:         }
541:     case usb_redir_start_bulk_receiving:
542:         if (command_for_host) {
543:             return sizeof(struct usb_redir_start_bulk_receiving_header);
544:         } else {
545:             return -1;
546:         }
547:     case usb_redir_stop_bulk_receiving:
548:         if (command_for_host) {
549:             return sizeof(struct usb_redir_stop_bulk_receiving_header);
550:         } else {
551:             return -1;
552:         }
553:     case usb_redir_bulk_receiving_status:
554:         if (!command_for_host) {
555:             return sizeof(struct usb_redir_bulk_receiving_status_header);
556:         } else {
557:             return -1;
558:         }
559:     case usb_redir_control_packet:
560:         return sizeof(struct usb_redir_control_packet_header);
561:     case usb_redir_bulk_packet:
562:         if (usbredirparser_have_cap(parser_pub,
563:                                 usb_redir_cap_32bits_bulk_length) &&
564:             usbredirparser_peer_has_cap(parser_pub,
565:                                 usb_redir_cap_32bits_bulk_length)) {
566:             return sizeof(struct usb_redir_bulk_packet_header);
567:         } else {
568:             return sizeof(struct usb_redir_bulk_packet_header_16bit_length);
569:         }
570:     case usb_redir_iso_packet:
571:         return sizeof(struct usb_redir_iso_packet_header);
572:     case usb_redir_interrupt_packet:
573:         return sizeof(struct usb_redir_interrupt_packet_header);
574:     case usb_redir_buffered_bulk_packet:
575:         if (!command_for_host) {
576:             return sizeof(struct usb_redir_buffered_bulk_packet_header);
577:         } else {
578:             return -1;
579:         }
580:     default:
581:         return -1;
582:     }
583: }
