585: /* Note this function only checks if extra data is allowed for the
586:    packet type being read at all, a check if it is actually allowed
587:    given the direction of the packet + ep is done in _verify_type_header */
588: static int usbredirparser_expect_extra_data(struct usbredirparser_priv *parser)
589: {
590:     switch (parser->header.type) {
591:     case usb_redir_hello: /* For the variable length capabilities array */
592:     case usb_redir_filter_filter:
593:     case usb_redir_control_packet:
594:     case usb_redir_bulk_packet:
595:     case usb_redir_iso_packet:
596:     case usb_redir_interrupt_packet:
597:     case usb_redir_buffered_bulk_packet:
598:         return 1;
599:     default:
600:         return 0;
601:     }
602: }
