604: static int usbredirparser_verify_bulk_recv_cap(
605:     struct usbredirparser *parser_pub, int send)
606: {
607:     struct usbredirparser_priv *parser =
608:         (struct usbredirparser_priv *)parser_pub;
609: 
610:     if ((send && !usbredirparser_peer_has_cap(parser_pub,
611:                                               usb_redir_cap_bulk_receiving)) ||
612:         (!send && !usbredirparser_have_cap(parser_pub,
613:                                            usb_redir_cap_bulk_receiving))) {
614:         ERROR("error bulk_receiving without cap_bulk_receiving");
615:         return 0;
616:     }
617:     return 1; /* Verify ok */
618: }
