620: static int usbredirparser_verify_type_header(
621:     struct usbredirparser *parser_pub,
622:     int32_t type, void *header, uint8_t *data, int data_len, int send)
623: {
624:     struct usbredirparser_priv *parser =
625:         (struct usbredirparser_priv *)parser_pub;
626:     int command_for_host = 0, expect_extra_data = 0;
627:     uint32_t length = 0;
628:     int ep = -1;
629: 
630:     if (parser->flags & usbredirparser_fl_usb_host) {
631:         command_for_host = 1;
632:     }
633:     if (send) {
634:         command_for_host = !command_for_host;
635:     }
636: 
637:     switch (type) {
638:     case usb_redir_interface_info: {
639:         struct usb_redir_interface_info_header *intf_info = header;
640: 
641:         if (intf_info->interface_count > 32) {
642:             ERROR("error interface_count > 32");
643:             return 0;
644:         }
645:         break;
646:     }
647:     case usb_redir_start_interrupt_receiving: {
648:         struct usb_redir_start_interrupt_receiving_header *start_int = header;
649: 
650:         if (!(start_int->endpoint & 0x80)) {
651:             ERROR("start int receiving on non input ep %02x",
652:                   start_int->endpoint);
653:             return 0;
654:         }
655:         break;
656:     }
657:     case usb_redir_stop_interrupt_receiving: {
658:         struct usb_redir_stop_interrupt_receiving_header *stop_int = header;
659: 
660:         if (!(stop_int->endpoint & 0x80)) {
661:             ERROR("stop int receiving on non input ep %02x",
662:                   stop_int->endpoint);
663:             return 0;
664:         }
665:         break;
666:     }
667:     case usb_redir_interrupt_receiving_status: {
668:         struct usb_redir_interrupt_receiving_status_header *int_status = header;
669: 
670:         if (!(int_status->endpoint & 0x80)) {
671:             ERROR("int receiving status for non input ep %02x",
672:                   int_status->endpoint);
673:             return 0;
674:         }
675:         break;
676:     }
677:     case usb_redir_filter_reject:
678:         if ((send && !usbredirparser_peer_has_cap(parser_pub,
679:                                              usb_redir_cap_filter)) ||
680:             (!send && !usbredirparser_have_cap(parser_pub,
681:                                              usb_redir_cap_filter))) {
682:             ERROR("error filter_reject without cap_filter");
683:             return 0;
684:         }
685:         break;
686:     case usb_redir_filter_filter:
687:         if ((send && !usbredirparser_peer_has_cap(parser_pub,
688:                                              usb_redir_cap_filter)) ||
689:             (!send && !usbredirparser_have_cap(parser_pub,
690:                                              usb_redir_cap_filter))) {
691:             ERROR("error filter_filter without cap_filter");
692:             return 0;
693:         }
694:         if (data_len < 1) {
695:             ERROR("error filter_filter without data");
696:             return 0;
697:         }
698:         if (data[data_len - 1] != 0) {
699:             ERROR("error non 0 terminated filter_filter data");
700:             return 0;
701:         }
702:         break;
703:     case usb_redir_device_disconnect_ack:
704:         if ((send && !usbredirparser_peer_has_cap(parser_pub,
705:                                      usb_redir_cap_device_disconnect_ack)) ||
706:             (!send && !usbredirparser_have_cap(parser_pub,
707:                                      usb_redir_cap_device_disconnect_ack))) {
708:             ERROR("error device_disconnect_ack without cap_device_disconnect_ack");
709:             return 0;
710:         }
711:         break;
712:     case usb_redir_start_bulk_receiving: {
713:         struct usb_redir_start_bulk_receiving_header *start_bulk = header;
714: 
715:         if (!usbredirparser_verify_bulk_recv_cap(parser_pub, send)) {
716:             return 0;
717:         }
718:         if (start_bulk->bytes_per_transfer > MAX_BULK_TRANSFER_SIZE) {
719:             ERROR("start bulk receiving length exceeds limits %u > %u",
720:                   start_bulk->bytes_per_transfer, MAX_BULK_TRANSFER_SIZE);
721:             return 0;
722:         }
723:         if (!(start_bulk->endpoint & 0x80)) {
724:             ERROR("start bulk receiving on non input ep %02x",
725:                   start_bulk->endpoint);
726:             return 0;
727:         }
728:         break;
729:     }
730:     case usb_redir_stop_bulk_receiving: {
731:         struct usb_redir_stop_bulk_receiving_header *stop_bulk = header;
732: 
733:         if (!usbredirparser_verify_bulk_recv_cap(parser_pub, send)) {
734:             return 0;
735:         }
736:         if (!(stop_bulk->endpoint & 0x80)) {
737:             ERROR("stop bulk receiving on non input ep %02x",
738:                   stop_bulk->endpoint);
739:             return 0;
740:         }
741:         break;
742:     }
743:     case usb_redir_bulk_receiving_status: {
744:         struct usb_redir_bulk_receiving_status_header *bulk_status = header;
745: 
746:         if (!usbredirparser_verify_bulk_recv_cap(parser_pub, send)) {
747:             return 0;
748:         }
749:         if (!(bulk_status->endpoint & 0x80)) {
750:             ERROR("bulk receiving status for non input ep %02x",
751:                   bulk_status->endpoint);
752:             return 0;
753:         }
754:         break;
755:     }
756:     case usb_redir_control_packet:
757:         length = ((struct usb_redir_control_packet_header *)header)->length;
758:         ep = ((struct usb_redir_control_packet_header *)header)->endpoint;
759:         break;
760:     case usb_redir_bulk_packet: {
761:         struct usb_redir_bulk_packet_header *bulk_packet = header;
762:         if (usbredirparser_have_cap(parser_pub,
763:                                 usb_redir_cap_32bits_bulk_length) &&
764:             usbredirparser_peer_has_cap(parser_pub,
765:                                 usb_redir_cap_32bits_bulk_length)) {
766:             length = (((uint32_t)bulk_packet->length_high) << 16) | bulk_packet->length;
767:         } else {
768:             length = bulk_packet->length;
769:             if (!send)
770:                 bulk_packet->length_high = 0;
771:         }
772:         if (length > MAX_BULK_TRANSFER_SIZE) {
773:             ERROR("bulk transfer length exceeds limits %u > %u",
774:                   (uint32_t)length, MAX_BULK_TRANSFER_SIZE);
775:             return 0;
776:         }
777:         ep = bulk_packet->endpoint;
778:         break;
779:     }
780:     case usb_redir_iso_packet:
781:         length = ((struct usb_redir_iso_packet_header *)header)->length;
782:         ep = ((struct usb_redir_iso_packet_header *)header)->endpoint;
783:         break;
784:     case usb_redir_interrupt_packet:
785:         length = ((struct usb_redir_interrupt_packet_header *)header)->length;
786:         ep = ((struct usb_redir_interrupt_packet_header *)header)->endpoint;
787:         break;
788:     case usb_redir_buffered_bulk_packet: {
789:         struct usb_redir_buffered_bulk_packet_header *buf_bulk_pkt = header;
790:         length = buf_bulk_pkt->length;
791:         if (!usbredirparser_verify_bulk_recv_cap(parser_pub, send)) {
792:             return 0;
793:         }
794:         if ((uint32_t)length > MAX_BULK_TRANSFER_SIZE) {
795:             ERROR("buffered bulk transfer length exceeds limits %u > %u",
796:                   (uint32_t)length, MAX_BULK_TRANSFER_SIZE);
797:             return 0;
798:         }
799:         ep = buf_bulk_pkt->endpoint;
800:         break;
801:     }
802:     }
803: 
804:     if (ep != -1) {
805:         if (((ep & 0x80) && !command_for_host) ||
806:             (!(ep & 0x80) && command_for_host)) {
807:             expect_extra_data = 1;
808:         }
809:         if (expect_extra_data) {
810:             if (data_len != length) {
811:                 ERROR("error data len %d != header len %d ep %02X",
812:                       data_len, length, ep);
813:                 return 0;
814:             }
815:         } else {
816:             if (data || data_len) {
817:                 ERROR("error unexpected extra data ep %02X", ep);
818:                 return 0;
819:             }
820:             switch (type) {
821:             case usb_redir_iso_packet:
822:                 ERROR("error iso packet send in wrong direction");
823:                 return 0;
824:             case usb_redir_interrupt_packet:
825:                 if (command_for_host) {
826:                     ERROR("error interrupt packet send in wrong direction");
827:                     return 0;
828:                 }
829:                 break;
830:             case usb_redir_buffered_bulk_packet:
831:                 ERROR("error buffered bulk packet send in wrong direction");
832:                 return 0;
833:             }
834:         }
835:     }
836: 
837:     return 1; /* Verify ok */
838: }
