840: static void usbredirparser_call_type_func(struct usbredirparser *parser_pub,
841:     bool *data_ownership_transferred)
842: {
843:     struct usbredirparser_priv *parser =
844:         (struct usbredirparser_priv *)parser_pub;
845:     uint64_t id;
846: 
847:     if (usbredirparser_using_32bits_ids(parser_pub))
848:         id = parser->header_32bit_id.id;
849:     else
850:         id = parser->header.id;
851: 
852:     switch (parser->header.type) {
853:     case usb_redir_hello:
854:         usbredirparser_handle_hello(parser_pub,
855:             (struct usb_redir_hello_header *)parser->type_header,
856:             parser->data, parser->data_len);
857:         break;
858:     case usb_redir_device_connect:
859:         parser->callb.device_connect_func(parser->callb.priv,
860:             (struct usb_redir_device_connect_header *)parser->type_header);
861:         break;
862:     case usb_redir_device_disconnect:
863:         parser->callb.device_disconnect_func(parser->callb.priv);
864:         if (usbredirparser_peer_has_cap(parser_pub,
865:                                         usb_redir_cap_device_disconnect_ack))
866:             usbredirparser_queue(parser_pub, usb_redir_device_disconnect_ack,
867:                                  0, NULL, NULL, 0);
868:         break;
869:     case usb_redir_reset:
870:         parser->callb.reset_func(parser->callb.priv);
871:         break;
872:     case usb_redir_interface_info:
873:         parser->callb.interface_info_func(parser->callb.priv,
874:             (struct usb_redir_interface_info_header *)parser->type_header);
875:         break;
876:     case usb_redir_ep_info:
877:         parser->callb.ep_info_func(parser->callb.priv,
878:             (struct usb_redir_ep_info_header *)parser->type_header);
879:         break;
880:     case usb_redir_set_configuration:
881:         parser->callb.set_configuration_func(parser->callb.priv, id,
882:             (struct usb_redir_set_configuration_header *)parser->type_header);
883:         break;
884:     case usb_redir_get_configuration:
885:         parser->callb.get_configuration_func(parser->callb.priv, id);
886:         break;
887:     case usb_redir_configuration_status:
888:         parser->callb.configuration_status_func(parser->callb.priv, id,
889:           (struct usb_redir_configuration_status_header *)parser->type_header);
890:         break;
891:     case usb_redir_set_alt_setting:
892:         parser->callb.set_alt_setting_func(parser->callb.priv, id,
893:             (struct usb_redir_set_alt_setting_header *)parser->type_header);
894:         break;
895:     case usb_redir_get_alt_setting:
896:         parser->callb.get_alt_setting_func(parser->callb.priv, id,
897:             (struct usb_redir_get_alt_setting_header *)parser->type_header);
898:         break;
899:     case usb_redir_alt_setting_status:
900:         parser->callb.alt_setting_status_func(parser->callb.priv, id,
901:             (struct usb_redir_alt_setting_status_header *)parser->type_header);
902:         break;
903:     case usb_redir_start_iso_stream:
904:         parser->callb.start_iso_stream_func(parser->callb.priv, id,
905:             (struct usb_redir_start_iso_stream_header *)parser->type_header);
906:         break;
907:     case usb_redir_stop_iso_stream:
908:         parser->callb.stop_iso_stream_func(parser->callb.priv, id,
909:             (struct usb_redir_stop_iso_stream_header *)parser->type_header);
910:         break;
911:     case usb_redir_iso_stream_status:
912:         parser->callb.iso_stream_status_func(parser->callb.priv, id,
913:             (struct usb_redir_iso_stream_status_header *)parser->type_header);
914:         break;
915:     case usb_redir_start_interrupt_receiving:
916:         parser->callb.start_interrupt_receiving_func(parser->callb.priv, id,
917:             (struct usb_redir_start_interrupt_receiving_header *)
918:             parser->type_header);
919:         break;
920:     case usb_redir_stop_interrupt_receiving:
921:         parser->callb.stop_interrupt_receiving_func(parser->callb.priv, id,
922:             (struct usb_redir_stop_interrupt_receiving_header *)
923:             parser->type_header);
924:         break;
925:     case usb_redir_interrupt_receiving_status:
926:         parser->callb.interrupt_receiving_status_func(parser->callb.priv, id,
927:             (struct usb_redir_interrupt_receiving_status_header *)
928:             parser->type_header);
929:         break;
930:     case usb_redir_alloc_bulk_streams:
931:         parser->callb.alloc_bulk_streams_func(parser->callb.priv, id,
932:             (struct usb_redir_alloc_bulk_streams_header *)parser->type_header);
933:         break;
934:     case usb_redir_free_bulk_streams:
935:         parser->callb.free_bulk_streams_func(parser->callb.priv, id,
936:             (struct usb_redir_free_bulk_streams_header *)parser->type_header);
937:         break;
938:     case usb_redir_bulk_streams_status:
939:         parser->callb.bulk_streams_status_func(parser->callb.priv, id,
940:           (struct usb_redir_bulk_streams_status_header *)parser->type_header);
941:         break;
942:     case usb_redir_cancel_data_packet:
943:         parser->callb.cancel_data_packet_func(parser->callb.priv, id);
944:         break;
945:     case usb_redir_filter_reject:
946:         parser->callb.filter_reject_func(parser->callb.priv);
947:         break;
948:     case usb_redir_filter_filter: {
949:         struct usbredirfilter_rule *rules;
950:         int r, count;
951: 
952:         r = usbredirfilter_string_to_rules((char *)parser->data, ",", "|",
953:                                            &rules, &count);
954:         if (r) {
955:             ERROR("error parsing filter (%d), ignoring filter message", r);
956:             break;
957:         }
958:         parser->callb.filter_filter_func(parser->callb.priv, rules, count);
959:         break;
960:     }
961:     case usb_redir_device_disconnect_ack:
962:         parser->callb.device_disconnect_ack_func(parser->callb.priv);
963:         break;
964:     case usb_redir_start_bulk_receiving:
965:         parser->callb.start_bulk_receiving_func(parser->callb.priv, id,
966:             (struct usb_redir_start_bulk_receiving_header *)
967:             parser->type_header);
968:         break;
969:     case usb_redir_stop_bulk_receiving:
970:         parser->callb.stop_bulk_receiving_func(parser->callb.priv, id,
971:             (struct usb_redir_stop_bulk_receiving_header *)
972:             parser->type_header);
973:         break;
974:     case usb_redir_bulk_receiving_status:
975:         parser->callb.bulk_receiving_status_func(parser->callb.priv, id,
976:             (struct usb_redir_bulk_receiving_status_header *)
977:             parser->type_header);
978:         break;
979:     case usb_redir_control_packet:
980:         *data_ownership_transferred = true;
981:         parser->callb.control_packet_func(parser->callb.priv, id,
982:             (struct usb_redir_control_packet_header *)parser->type_header,
983:             parser->data, parser->data_len);
984:         break;
985:     case usb_redir_bulk_packet:
986:         *data_ownership_transferred = true;
987:         parser->callb.bulk_packet_func(parser->callb.priv, id,
988:             (struct usb_redir_bulk_packet_header *)parser->type_header,
989:             parser->data, parser->data_len);
990:         break;
991:     case usb_redir_iso_packet:
992:         *data_ownership_transferred = true;
993:         parser->callb.iso_packet_func(parser->callb.priv, id,
994:             (struct usb_redir_iso_packet_header *)parser->type_header,
995:             parser->data, parser->data_len);
996:         break;
997:     case usb_redir_interrupt_packet:
998:         *data_ownership_transferred = true;
999:         parser->callb.interrupt_packet_func(parser->callb.priv, id,
1000:             (struct usb_redir_interrupt_packet_header *)parser->type_header,
1001:             parser->data, parser->data_len);
1002:         break;
1003:     case usb_redir_buffered_bulk_packet:
1004:         *data_ownership_transferred = true;
1005:         parser->callb.buffered_bulk_packet_func(parser->callb.priv, id,
1006:           (struct usb_redir_buffered_bulk_packet_header *)parser->type_header,
1007:           parser->data, parser->data_len);
1008:         break;
1009:     }
1010: }
