1012: USBREDIR_VISIBLE
1013: int usbredirparser_do_read(struct usbredirparser *parser_pub)
1014: {
1015:     struct usbredirparser_priv *parser =
1016:         (struct usbredirparser_priv *)parser_pub;
1017:     int r, header_len, type_header_len, data_len;
1018:     bool data_ownership_transferred;
1019:     uint8_t *dest;
1020: 
1021:     header_len = usbredirparser_get_header_len(parser_pub);
1022: 
1023:     usbredirparser_assert_invariants(parser);
1024:     /* Skip forward to next packet (only used in error conditions) */
1025:     while (parser->to_skip > 0) {
1026:         uint8_t buf[65536];
1027:         r = (parser->to_skip > sizeof(buf)) ? sizeof(buf) : parser->to_skip;
1028:         r = parser->callb.read_func(parser->callb.priv, buf, r);
1029:         if (r <= 0) {
1030:             usbredirparser_assert_invariants(parser);
1031:             return r;
1032:         }
1033:         parser->to_skip -= r;
1034:     }
1035: 
1036:     /* Consume data until read would block or returns an error */
1037:     while (1) {
1038:         if (parser->header_read < header_len) {
1039:             r = header_len - parser->header_read;
1040:             dest = (uint8_t *)&parser->header + parser->header_read;
1041:         } else if (parser->type_header_read < parser->type_header_len) {
1042:             r = parser->type_header_len - parser->type_header_read;
1043:             dest = parser->type_header + parser->type_header_read;
1044:         } else {
1045:             r = parser->data_len - parser->data_read;
1046:             dest = parser->data + parser->data_read;
1047:         }
1048: 
1049:         if (r > 0) {
1050:             r = parser->callb.read_func(parser->callb.priv, dest, r);
1051:             if (r <= 0) {
1052:                 usbredirparser_assert_invariants(parser);
1053:                 return r;
1054:             }
1055:         }
1056: 
1057:         if (parser->header_read < header_len) {
1058:             parser->header_read += r;
1059:             if (parser->header_read == header_len) {
1060:                 type_header_len =
