1216:     uint8_t *buf, *type_header_out, *data_out;
1217:     struct usb_redir_header *header;
1218:     struct usbredirparser_buf *wbuf, *new_wbuf;
1219:     int header_len, type_header_len, total_size;
1220: 
1221:     header_len = usbredirparser_get_header_len(parser_pub);
1222:     type_header_len = usbredirparser_get_type_header_len(parser_pub, type, 1);
1223:     if (type_header_len < 0) { /* This should never happen */
1224:         ERROR("error packet type unknown with internal call, please report!!");
1225:         return;
1226:     }
1227: 
1228:     if (!usbredirparser_verify_type_header(parser_pub, type, type_header_in,
1229:                                            data_in, data_len, 1)) {
1230:         ERROR("error usbredirparser_send_* call invalid params, please report!!");
1231:         return;
1232:     }
1233: 
1234:     total_size = header_len + type_header_len + data_len;
1235:     new_wbuf = calloc(1, sizeof(*new_wbuf));
1236:     buf = malloc(total_size);
1237:     if (!new_wbuf || !buf) {
1238:         ERROR("Out of memory allocating buffer to send packet, dropping!");
1239:         free(new_wbuf); free(buf);
1240:         return;
1241:     }
1242: 
1243:     new_wbuf->buf = buf;
1244:     new_wbuf->len = total_size;
1245: 
1246:     header = (struct usb_redir_header *)buf;
1247:     type_header_out = buf + header_len;
1248:     data_out = type_header_out + type_header_len;
1249: 
1250:     header->type   = type;
1251:     header->length = type_header_len + data_len;
1252:     if (usbredirparser_using_32bits_ids(parser_pub))
1253:         ((struct usb_redir_header_32bit_id *)header)->id = id;
1254:     else
1255:         header->id = id;
1256:     memcpy(type_header_out, type_header_in, type_header_len);
1257:     memcpy(data_out, data_in, data_len);
