1259:     LOCK(parser);
1260:     if (!parser->write_buf) {
1261:         parser->write_buf = new_wbuf;
1262:     } else {
1263:         /* limiting the write_buf's stack depth is our users responsibility */
1264:         wbuf = parser->write_buf;
1265:         while (wbuf->next)
