270: static void usbredirhost_handle_disconnect(struct usbredirhost *host)
271: {
272:     /* Disconnect uses its own lock to avoid needing nesting capable locks */
273:     if (host->disconnect_lock) {
274:         host->parser->lock_func(host->disconnect_lock);
275:     }
276:     if (!host->disconnected) {
277:         INFO("device disconnected");
278:         usbredirparser_send_device_disconnect(host->parser);
279:         if (usbredirparser_peer_has_cap(host->parser,
280:                                         usb_redir_cap_device_disconnect_ack))
281:             host->wait_disconnect = 1;
282:         host->disconnected = 1;
283:     }
284:     if (host->disconnect_lock) {
285:         host->parser->unlock_func(host->disconnect_lock);
286:     }
287: }
