289: /* One function to convert either a transfer status code, or a libusb error
290:    code to a usb_redir status. We handle both in one conversion function so
291:    that we can pass error codes as status codes to the completion handler
292:    in case of submission error (the codes don't overlap), using the completion
293:    handler to report back the status and cleanup as it would on completion of
294:    a successfully submitted transfer. */
295: static int libusb_status_or_error_to_redir_status(struct usbredirhost *host,
296:                                                   int status)
297: {
298:     switch (status) {
299:         case LIBUSB_TRANSFER_COMPLETED:
300:             return usb_redir_success;
301:         case LIBUSB_TRANSFER_ERROR:
302:             return usb_redir_ioerror;
303:         case LIBUSB_TRANSFER_TIMED_OUT:
304:             return usb_redir_timeout;
305:         case LIBUSB_TRANSFER_CANCELLED:
306:             return usb_redir_cancelled;
307:         case LIBUSB_TRANSFER_STALL:
308:             return usb_redir_stall;
309:         case LIBUSB_TRANSFER_NO_DEVICE:
310:             usbredirhost_handle_disconnect(host);
311:             return usb_redir_ioerror;
312:         case LIBUSB_TRANSFER_OVERFLOW:
313:             return usb_redir_babble;
314: 
315:         case LIBUSB_ERROR_INVALID_PARAM:
316:             return usb_redir_inval;
317:         case LIBUSB_ERROR_NO_DEVICE:
318:             usbredirhost_handle_disconnect(host);
319:             return usb_redir_ioerror;
320:         case LIBUSB_ERROR_TIMEOUT:
321:             return usb_redir_timeout;
322:         default:
323:             return usb_redir_ioerror;
324:     }
325: }
