327: static void usbredirhost_set_max_packetsize(struct usbredirhost *host,
328:     uint8_t ep, uint16_t wMaxPacketSize)
329: {
330:     int maxp, mult = 1;
331: 
332:     maxp = wMaxPacketSize & 0x7ff;
333: 
334:     if (libusb_get_device_speed(host->dev) == LIBUSB_SPEED_HIGH &&
335:              host->endpoint[EP2I(ep)].type == usb_redir_type_iso) {
336:         switch ((wMaxPacketSize >> 11) & 3) {
337:         case 1:  mult = 2; break;
338:         case 2:  mult = 3; break;
339:         default: mult = 1; break;
340:         }
341:     }
342: 
343:     host->endpoint[EP2I(ep)].max_packetsize = maxp * mult;
344: }
