346: static void usbredirhost_set_max_streams(struct usbredirhost *host,
347:     const struct libusb_endpoint_descriptor *endp)
348: {
349: #if LIBUSBX_API_VERSION >= 0x01000102
350:     struct libusb_ss_endpoint_companion_descriptor *endp_ss_comp;
351:     int max_streams, i = EP2I(endp->bEndpointAddress);
352: 
353:     host->endpoint[i].max_streams = 0;
354: 
355:     if (host->endpoint[i].type == usb_redir_type_bulk &&
356:             libusb_get_ss_endpoint_companion_descriptor(host->ctx, endp,
357:                 &endp_ss_comp) == LIBUSB_SUCCESS) {
358:         max_streams = endp_ss_comp->bmAttributes & 0x1f;
359:         if (max_streams)
360:             host->endpoint[i].max_streams = 1 << max_streams;
361:         libusb_free_ss_endpoint_companion_descriptor(endp_ss_comp);
362:     }
363: #endif
364: }
