366: /* Called from open/close and parser read callbacks */
367: static void usbredirhost_send_interface_n_ep_info(struct usbredirhost *host)
368: {
369:     int i;
370:     const struct libusb_interface_descriptor *intf_desc;
371:     struct usb_redir_ep_info_header ep_info;
372:     struct usb_redir_interface_info_header interface_info = { 0, };
373: 
374:     if (host->config)
375:         interface_info.interface_count = host->config->bNumInterfaces;
376: 
377:     for (i = 0; i < interface_info.interface_count; i++) {
378:         intf_desc =
379:             &host->config->interface[i].altsetting[host->alt_setting[i]];
380: 
381:         interface_info.interface[i] = intf_desc->bInterfaceNumber;
382:         interface_info.interface_class[i] = intf_desc->bInterfaceClass;
383:         interface_info.interface_subclass[i] = intf_desc->bInterfaceSubClass;
384:         interface_info.interface_protocol[i] = intf_desc->bInterfaceProtocol;
385:     }
386:     usbredirparser_send_interface_info(host->parser, &interface_info);
387: 
388:     for (i = 0; i < MAX_ENDPOINTS; i++) {
389:         ep_info.type[i] = host->endpoint[i].type;
390:         ep_info.interval[i] = host->endpoint[i].interval;
391:         ep_info.interface[i] = host->endpoint[i].interface;
392:         ep_info.max_packet_size[i] = host->endpoint[i].max_packetsize;
393:         ep_info.max_streams[i] = host->endpoint[i].max_streams;
394:     }
395:     usbredirparser_send_ep_info(host->parser, &ep_info);
396: }
