398: /* Called from open/close and parser read callbacks */
399: static void usbredirhost_send_device_connect(struct usbredirhost *host)
400: {
401:     struct usb_redir_device_connect_header device_connect;
402:     enum libusb_speed speed;
403: 
404:     if (!host->disconnected) {
405:         ERROR("internal error sending device_connect but already connected");
406:         return;
407:     }
408: 
409:     if (!usbredirparser_have_peer_caps(host->parser) ||
410:             host->wait_disconnect) {
411:         host->connect_pending = 1;
412:         return;
413:     }
414: 
415:     speed = libusb_get_device_speed(host->dev);
416:     switch (speed) {
417:     case LIBUSB_SPEED_LOW:
418:         device_connect.speed = usb_redir_speed_low; break;
419:     case LIBUSB_SPEED_FULL:
420:         device_connect.speed = usb_redir_speed_full; break;
421:     case LIBUSB_SPEED_HIGH:
422:         device_connect.speed = usb_redir_speed_high; break;
423:     case LIBUSB_SPEED_SUPER:
424:         device_connect.speed = usb_redir_speed_super; break;
425:     default:
426:         device_connect.speed = usb_redir_speed_unknown;
427:     }
428:     device_connect.device_class = host->desc.bDeviceClass;
429:     device_connect.device_subclass = host->desc.bDeviceSubClass;
430:     device_connect.device_protocol = host->desc.bDeviceProtocol;
431:     device_connect.vendor_id = host->desc.idVendor;
432:     device_connect.product_id = host->desc.idProduct;
433:     device_connect.device_version_bcd = host->desc.bcdDevice;
434: 
435:     usbredirhost_send_interface_n_ep_info(host);
436:     usbredirparser_send_device_connect(host->parser, &device_connect);
437:     host->connect_pending = 0;
438:     host->disconnected = 0; /* The guest may now use the device */
439: 
440:     FLUSH(host);
441: }
