443: /* Called from open/close and parser read callbacks */
444: static void usbredirhost_parse_interface(struct usbredirhost *host, int i)
445: {
446:     int j;
447:     const struct libusb_interface_descriptor *intf_desc;
448:     uint8_t ep_address;
449: 
450:     intf_desc =
451:         &host->config->interface[i].altsetting[host->alt_setting[i]];
452: 
453:     for (j = 0; j < intf_desc->bNumEndpoints; j++) {
454:         ep_address = intf_desc->endpoint[j].bEndpointAddress;
455:         host->endpoint[EP2I(ep_address)].type =
456:             intf_desc->endpoint[j].bmAttributes & LIBUSB_TRANSFER_TYPE_MASK;
457:         host->endpoint[EP2I(ep_address)].interval =
458:             intf_desc->endpoint[j].bInterval;
459:         host->endpoint[EP2I(ep_address)].interface =
460:             intf_desc->bInterfaceNumber;
461:         usbredirhost_set_max_packetsize(host, ep_address,
462:                                         intf_desc->endpoint[j].wMaxPacketSize);
463:         usbredirhost_set_max_streams(host, &intf_desc->endpoint[j]);
464:         host->endpoint[EP2I(ep_address)].warn_on_drop = 1;
465:     }
466: }
