468: static void usbredirhost_parse_config(struct usbredirhost *host)
469: {
470:     int i;
471: 
472:     for (i = 0; i < MAX_ENDPOINTS; i++) {
473:         if ((i & 0x0f) == 0) {
474:             host->endpoint[i].type = usb_redir_type_control;
475:         } else {
476:             host->endpoint[i].type = usb_redir_type_invalid;
477:         }
478:         host->endpoint[i].interval = 0;
479:         host->endpoint[i].interface = 0;
480:         host->endpoint[i].max_packetsize = 0;
481:         host->endpoint[i].max_streams = 0;
482:     }
483: 
484:     for (i = 0; host->config && i < host->config->bNumInterfaces; i++) {
485:         usbredirhost_parse_interface(host, i);
486:     }
487: }
