489: /* Called from open/close and parser read callbacks */
490: static int usbredirhost_claim(struct usbredirhost *host, int initial_claim)
491: {
492:     int i, n, r;
493: 
494:     if (host->config) {
495:         libusb_free_config_descriptor(host->config);
496:         host->config = NULL;
497:     }
498: 
499:     r = libusb_get_device_descriptor(host->dev, &host->desc);
500:     if (r < 0) {
501:         ERROR("could not get device descriptor: %s", libusb_error_name(r));
502:         return libusb_status_or_error_to_redir_status(host, r);
503:     }
504: 
505:     r = libusb_get_active_config_descriptor(host->dev, &host->config);
506:     if (r < 0 && r != LIBUSB_ERROR_NOT_FOUND) {
507:         ERROR("could not get descriptors for active configuration: %s",
508:               libusb_error_name(r));
509:         return libusb_status_or_error_to_redir_status(host, r);
510:     }
511:     if (host->config && host->config->bNumInterfaces > MAX_INTERFACES) {
512:         ERROR("usb decriptor has too much intefaces (%d > %d)",
513:               (int)host->config->bNumInterfaces, MAX_INTERFACES);
514:         return usb_redir_ioerror;
515:     }
516: 
517:     if (initial_claim) {
518:         if (host->config)
519:             host->restore_config = host->config->bConfigurationValue;
520:         else
521:             host->restore_config = -1; /* unconfigured */
522: 
523:         /* If the device is unconfigured and has only 1 config, we assume
524:            this is the result of the user doing "safely remove hardware",
525:            and we try to reset the device configuration to this config when
526:            we release the device, so that it becomes usable again. */
527:         if (host->restore_config == -1 && host->desc.bNumConfigurations == 1) {
528:             struct libusb_config_descriptor *config;
529: 
530:             r = libusb_get_config_descriptor(host->dev, 0, &config);
531:             if (r == 0) {
532:                 host->restore_config = config->bConfigurationValue;
533:                 libusb_free_config_descriptor(config);
534:             }
535:         }
536:     }
537: 
538:     /* All interfaces begin at alt setting 0 when (re)claimed */
539:     memset(host->alt_setting, 0, MAX_INTERFACES);
540: 
541:     host->claimed = 1;
542: #if LIBUSBX_API_VERSION >= 0x01000102
543:     libusb_set_auto_detach_kernel_driver(host->handle, 1);
544: #endif
545:     for (i = 0; host->config && i < host->config->bNumInterfaces; i++) {
546:         n = host->config->interface[i].altsetting[0].bInterfaceNumber;
547: 
548: #if LIBUSBX_API_VERSION < 0x01000102
549:         r = libusb_detach_kernel_driver(host->handle, n);
550:         if (r < 0 && r != LIBUSB_ERROR_NOT_FOUND
551:                   && r != LIBUSB_ERROR_NOT_SUPPORTED) {
552:             ERROR("could not detach driver from interface %d (configuration %d): %s",
553:                   n, host->config->bConfigurationValue, libusb_error_name(r));
554:             return libusb_status_or_error_to_redir_status(host, r);
555:         }
556: #endif
557: 
558:         r = libusb_claim_interface(host->handle, n);
559:         if (r < 0) {
560:             if (r == LIBUSB_ERROR_BUSY)
561:                 ERROR("Device is in use by another application");
562:             else
563:                 ERROR("could not claim interface %d (configuration %d): %s",
564:                       n, host->config->bConfigurationValue,
565:                       libusb_error_name(r));
566:             return libusb_status_or_error_to_redir_status(host, r);
567:         }
568:     }
569: 
570:     usbredirhost_parse_config(host);
571:     return usb_redir_success;
572: }
