574: /* Called from open/close and parser read callbacks */
575: static void usbredirhost_release(struct usbredirhost *host, int attach_drivers)
576: {
577:     int i, n, r, current_config = -1;
578: 
579:     if (!host->claimed)
580:         return;
581: 
582: #if LIBUSBX_API_VERSION >= 0x01000102
583:     /* We want to always do the attach ourselves because:
584:        1) For compound interfaces such as usb-audio we must first release all
585:           interfaces before we can attach the driver;
586:        2) When releasing interfaces before calling libusb_set_configuration,
587:           we don't want the kernel driver to get attached (our attach_drivers
588:           parameter is 0 in this case). */
589:     libusb_set_auto_detach_kernel_driver(host->handle, 0);
590: #endif
591: 
592:     for (i = 0; host->config && i < host->config->bNumInterfaces; i++) {
593:         n = host->config->interface[i].altsetting[0].bInterfaceNumber;
594: 
595:         r = libusb_release_interface(host->handle, n);
596:         if (r < 0 && r != LIBUSB_ERROR_NOT_FOUND
597:                   && r != LIBUSB_ERROR_NO_DEVICE) {
598:             ERROR("could not release interface %d (configuration %d): %s",
599:                   n, host->config->bConfigurationValue, libusb_error_name(r));
600:         }
601:     }
602: 
603:     if (!attach_drivers)
604:         return;
605: 
606:     host->claimed = 0;
607: 
608:     /* reset the device before re-binding the kernel drivers, so that the
609:        kernel drivers get the device in a clean state. */
610:     if (!(host->quirks & QUIRK_DO_NOT_RESET)) {
611:         r = libusb_reset_device(host->handle);
612:         if (r != 0) {
613:             /* if we're releasing the device because it was removed, resetting
614:              * will fail. Don't print a warning in this situation */
615:             if (r != LIBUSB_ERROR_NO_DEVICE) {
616:                 ERROR("error resetting device: %s", libusb_error_name(r));
617:             }
618:             return;
619:         }
620:     }
621: 
622:     if (host->config)
623:         current_config = host->config->bConfigurationValue;
624: 
625:     if (current_config != host->restore_config) {
626:         r = libusb_set_configuration(host->handle, host->restore_config);
627:         if (r < 0)
628:             ERROR("could not restore configuration to %d: %s",
629:                   host->restore_config, libusb_error_name(r));
630:         return; /* set_config automatically binds drivers for the new config */
631:     }
632: 
633:     for (i = 0; host->config && i < host->config->bNumInterfaces; i++) {
634:         n = host->config->interface[i].altsetting[0].bInterfaceNumber;
635:         r = libusb_attach_kernel_driver(host->handle, n);
636:         if (r < 0 && r != LIBUSB_ERROR_NOT_FOUND /* No driver */
637:                   && r != LIBUSB_ERROR_NO_DEVICE /* Device unplugged */
638:                   && r != LIBUSB_ERROR_NOT_SUPPORTED /* Not supported */
639:                   && r != LIBUSB_ERROR_BUSY /* driver rebound already */) {
640:             ERROR("could not re-attach driver to interface %d (configuration %d): %s",
641:                   n, host->config->bConfigurationValue, libusb_error_name(r));
642:         }
643:     }
644: }
