803: static int usbredirhost_reset_device(struct usbredirhost *host)
804: {
805:     int r;
806: 
807:     if (host->quirks & QUIRK_DO_NOT_RESET) {
808:         return 0;
809:     }
810: 
811:     r = libusb_reset_device(host->handle);
812:     if (r != 0) {
813:         ERROR("error resetting device: %s", libusb_error_name(r));
814:         usbredirhost_clear_device(host);
815:         return r;
816:     }
817: 
818:     host->reset = 1;
819:     return 0;
820: }
