822: USBREDIR_VISIBLE
823: int usbredirhost_set_device(struct usbredirhost *host,
824:                              libusb_device_handle *usb_dev_handle)
825: {
826:     int i, r, status;
827: 
828:     usbredirhost_clear_device(host);
829: 
830:     if (!usb_dev_handle)
831:         return usb_redir_success;
832: 
833:     host->dev = libusb_get_device(usb_dev_handle);
834:     host->handle = usb_dev_handle;
835: 
836:     status = usbredirhost_claim(host, 1);
837:     if (status != usb_redir_success) {
838:         usbredirhost_clear_device(host);
839:         return status;
840:     }
841: 
842:     for (i = 0; usbredirhost_reset_blacklist[i].vendor_id != -1; i++) {
843:         if (host->desc.idVendor == usbredirhost_reset_blacklist[i].vendor_id &&
844:             host->desc.idProduct ==
845:                                 usbredirhost_reset_blacklist[i].product_id) {
846:             host->quirks |= QUIRK_DO_NOT_RESET;
847:             break;
848:         }
849:     }
850: 
851:     /* The first thing almost any usb-guest does is a (slow) device-reset
852:        so lets do that before hand */
853:     r = usbredirhost_reset_device(host);
854:     if (r != 0) {
855:         return libusb_status_or_error_to_redir_status(host, r);
856:     }
857: 
858:     usbredirhost_send_device_connect(host);
859: 
860:     return usb_redir_success;
861: }
