863: static void usbredirhost_clear_device(struct usbredirhost *host)
864: {
865:     if (!host->dev)
866:         return;
867: 
868:     if (usbredirhost_cancel_pending_urbs(host, 0))
869:         usbredirhost_wait_for_cancel_completion(host);
870: 
871:     usbredirhost_release(host, 1);
872: 
873:     if (host->config) {
874:         libusb_free_config_descriptor(host->config);
875:         host->config = NULL;
876:     }
877:     if (host->handle) {
878:         libusb_close(host->handle);
879:         host->handle = NULL;
880:     }
881: 
882:     host->connect_pending = 0;
883:     host->quirks = 0;
884:     host->dev = NULL;
885: 
886:     usbredirhost_handle_disconnect(host);
887:     FLUSH(host);
888: }
