965: static void usbredirhost_remove_and_free_transfer(
966:     struct usbredirtransfer *transfer)
967: {
968:     if (transfer->next)
969:         transfer->next->prev = transfer->prev;
970:     if (transfer->prev)
971:         transfer->prev->next = transfer->next;
972:     usbredirhost_free_transfer(transfer);
