977: /* Called from both parser read and packet complete callbacks */
978: static void usbredirhost_cancel_stream_unlocked(struct usbredirhost *host,
979:     uint8_t ep)
980: {
981:     int i;
982:     struct usbredirtransfer *transfer;
983: 
984:     for (i = 0; i < host->endpoint[EP2I(ep)].transfer_count; i++) {
985:         transfer = host->endpoint[EP2I(ep)].transfer[i];
986:         if (transfer->packet_idx == SUBMITTED_IDX) {
987:             libusb_cancel_transfer(transfer->transfer);
988:             transfer->cancelled = 1;
989:             host->cancels_pending++;
990:         } else {
991:             usbredirhost_free_transfer(transfer);
992:         }
993:         host->endpoint[EP2I(ep)].transfer[i] = NULL;
994:     }
995:     host->endpoint[EP2I(ep)].out_idx = 0;
996:     host->endpoint[EP2I(ep)].stream_started = 0;
997:     host->endpoint[EP2I(ep)].drop_packets = 0;
998:     host->endpoint[EP2I(ep)].pkts_per_transfer = 0;
999:     host->endpoint[EP2I(ep)].transfer_count = 0;
1000: }
