1002: static void usbredirhost_cancel_stream(struct usbredirhost *host,
1003:     uint8_t ep)
1004: {
1005:     LOCK(host);
1006:     usbredirhost_cancel_stream_unlocked(host, ep);
1007:     UNLOCK(host);
