1010: static void usbredirhost_send_stream_status(struct usbredirhost *host,
1011:     uint64_t id, uint8_t ep, uint8_t status)
1012: {
1013:     switch (host->endpoint[EP2I(ep)].type) {
1014:     case usb_redir_type_iso: {
1015:         struct usb_redir_iso_stream_status_header iso_status = {
1016:             .endpoint = ep,
1017:             .status   = status,
1018:         };
1019:         usbredirparser_send_iso_stream_status(host->parser, id, &iso_status);
1020:         break;
1021:     }
1022:     case usb_redir_type_bulk: {
1023:         struct usb_redir_bulk_receiving_status_header bulk_status = {
1024:             .endpoint = ep,
1025:             .status   = status,
1026:         };
1027:         usbredirparser_send_bulk_receiving_status(host->parser, id,
1028:                                                   &bulk_status);
1029:         break;
1030:     }
1031:     case usb_redir_type_interrupt: {
1032:         struct usb_redir_interrupt_receiving_status_header interrupt_status = {
1033:             .endpoint = ep,
1034:             .status   = status,
1035:         };
1036:         usbredirparser_send_interrupt_receiving_status(host->parser, id,
1037:                                                        &interrupt_status);
1038:         break;
1039:     }
1040:     }
1041: }
