1043: static int usbredirhost_can_write_iso_package(struct usbredirhost *host)
1044: {
1045:     uint64_t size;
1046: 
1047:     if (host->flags & usbredirhost_fl_write_cb_owns_buffer) {
1048:         if (!host->buffered_output_size_func) {
1049:             /* Application is not dropping isoc packages */
1050:             return true;
1051:         }
1052:         size = host->buffered_output_size_func(host->func_priv);
1053:     } else {
1054:         /* queue is on usbredirparser */
1055:         size = usbredirparser_get_bufferered_output_size(host->parser);
1056:     }
1057: 
1058:     if (size >= host->iso_threshold.higher) {
1059:         if (!host->iso_threshold.dropping)
1060:             DEBUG("START dropping isoc packets %" PRIu64 " buffer > %" PRIu64 " hi threshold",
1061:                   size, host->iso_threshold.higher);
1062:         host->iso_threshold.dropping = true;
1063:     } else if (size < host->iso_threshold.lower) {
1064:         if (host->iso_threshold.dropping)
1065:             DEBUG("STOP dropping isoc packets %" PRIu64 " buffer < %" PRIu64 " low threshold",
1066:                   size, host->iso_threshold.lower);
1067: 
1068:         host->iso_threshold.dropping = false;
1069:     }
1070: 
1071:     return !host->iso_threshold.dropping;
1072: }
