1074: static void usbredirhost_send_stream_data(struct usbredirhost *host,
1075:     uint64_t id, uint8_t ep, uint8_t status, uint8_t *data, int len)
1076: {
1077:     /* USB-2 is max 8000 packets / sec, if we've queued up more then 0.1 sec,
1078:        assume our connection is not keeping up and start dropping packets. */
1079:     if (usbredirparser_has_data_to_write(host->parser) > 800) {
1080:         if (host->endpoint[EP2I(ep)].warn_on_drop) {
1081:             WARNING("buffered stream on endpoint %02X, connection too slow, "
1082:                     "dropping packets", ep);
1083:             host->endpoint[EP2I(ep)].warn_on_drop = 0;
1084:         }
1085:         DEBUG("buffered complete ep %02X dropping packet status %d len %d",
1086:               ep, status, len);
1087:         return;
1088:     }
1089: 
1090:     DEBUG("buffered complete ep %02X status %d len %d", ep, status, len);
1091: 
1092:     switch (host->endpoint[EP2I(ep)].type) {
1093:     case usb_redir_type_iso: {
1094:         struct usb_redir_iso_packet_header iso_packet = {
1095:             .endpoint = ep,
1096:             .status   = status,
1097:             .length   = len,
1098:         };
1099: 
1100:         if (usbredirhost_can_write_iso_package(host))
1101:             usbredirparser_send_iso_packet(host->parser, id, &iso_packet,
1102:                                            data, len);
1103:         break;
1104:     }
1105:     case usb_redir_type_bulk: {
1106:         struct usb_redir_buffered_bulk_packet_header bulk_packet = {
1107:             .endpoint = ep,
1108:             .status   = status,
1109:             .length   = len,
1110:         };
1111:         usbredirparser_send_buffered_bulk_packet(host->parser, id,
1112:                                                  &bulk_packet, data, len);
1113:         break;
1114:     }
1115:     case usb_redir_type_interrupt: {
1116:         struct usb_redir_interrupt_packet_header interrupt_packet = {
1117:             .endpoint = ep,
1118:             .status   = status,
1119:             .length   = len,
1120:         };
1121:         usbredirparser_send_interrupt_packet(host->parser, id,
1122:                                              &interrupt_packet, data, len);
1123:         break;
1124:     }
1125:     }
1126: }
