1128: /* Called from both parser read and packet complete callbacks */
1129: static int usbredirhost_submit_stream_transfer_unlocked(
1130:     struct usbredirhost *host, struct usbredirtransfer *transfer)
1131: {
1132:     int r;
1133: 
1134:     host->reset = 0;
1135: 
1136:     r = libusb_submit_transfer(transfer->transfer);
1137:     if (r < 0) {
1138:         uint8_t ep = transfer->transfer->endpoint;
1139:         if (r == LIBUSB_ERROR_NO_DEVICE) {
1140:             usbredirhost_handle_disconnect(host);
1141:         } else {
1142:             ERROR("error submitting transfer on ep %02X: %s, stopping stream",
1143:                   ep, libusb_error_name(r));
1144:             usbredirhost_cancel_stream_unlocked(host, ep);
1145:             usbredirhost_send_stream_status(host, transfer->id, ep,
1146:                                             usb_redir_stall);
1147:         }
1148:         return usb_redir_stall;
1149:     }
1150: 
1151:     transfer->packet_idx = SUBMITTED_IDX;
1152:     return usb_redir_success;
1153: }
