1155: /* Called from both parser read and packet complete callbacks */
1156: static int usbredirhost_start_stream_unlocked(struct usbredirhost *host,
1157:     uint8_t ep)
1158: {
1159:     unsigned int i, count = host->endpoint[EP2I(ep)].transfer_count;
1160:     int status;
1161: 
1162:     /* For out endpoints 1/2 the transfers are a buffer for usb-guest data */
1163:     if (!(ep & LIBUSB_ENDPOINT_IN)) {
1164:         count /= 2;
1165:     }
