#define BULK_TIMEOUT          0 /* No timeout for bulk transfers */
#define ISO_TIMEOUT        1000
#define INTERRUPT_TIMEOUT     0 /* No timeout for interrupt transfers */

#define MAX_TRANSFER_COUNT        16
#define MAX_PACKETS_PER_TRANSFER  32
