138:     if (!g_option_context_parse(ctx, argc, argv, &err)) {
139:         g_printerr("Could not parse arguments: %s\n", err->message);
140:         g_printerr("%s", g_option_context_get_help(ctx, TRUE, NULL));
141:         g_clear_error(&err);
