175: end:
176:     if (self) {
177:         g_debug("Device: '%04x:%04x', %s addr: '%s', port: %d\n",
178:                 self->device.vendor,
179:                 self->device.product,
180:                 self->is_client ? "client connect" : "server at",
181:                 self->addr,
