284: static int
285: usbredir_read_cb(void *priv, uint8_t *data, int count)
286: {
287:     redirect *self = (redirect *) priv;
288:     GIOStream *iostream = G_IO_STREAM(self->connection);
289:     GError *err = NULL;
290: 
291:     GPollableInputStream *instream = G_POLLABLE_INPUT_STREAM(g_io_stream_get_input_stream(iostream));
292:     gssize nbytes = g_pollable_input_stream_read_nonblocking(instream,
293:             data,
294:             count,
295:             NULL,
296:             &err);
297:     if (nbytes <= 0) {
298:         if (g_error_matches(err, G_IO_ERROR, G_IO_ERROR_WOULD_BLOCK)) {
299:             /* Try again later */
300:             nbytes = 0;
301:         } else {
302:             if (err != NULL) {
303:                 g_warning("Failure at %s: %s", __func__, err->message);
304:             }
305:             g_main_loop_quit(self->main_loop);
306:         }
307:         g_clear_error(&err);
308:     }
309:     return nbytes;
310: }
