392: static gboolean
393: connection_handle_io_cb(GIOChannel *source, GIOCondition condition, gpointer user_data)
394: {
395:     redirect *self = (redirect *) user_data;
396: 
397:     if (condition & G_IO_ERR || condition & G_IO_HUP) {
398:         g_warning("Connection: err=%d, hup=%d - exiting", (condition & G_IO_ERR), (condition & G_IO_HUP));
399:         goto end;
400:     }
401: 
402:     if (condition & G_IO_IN) {
403:         int ret = usbredirhost_read_guest_data(self->usbredirhost);
404:         if (ret < 0) {
405:             g_critical("%s: Failed to read guest", __func__);
406:             goto end;
407:         }
408:     }
409:     // try to write data in any case, to avoid having another iteration and
410:     // creation of another watch if there is space in output buffer
411:     if (usbredirhost_has_data_to_write(self->usbredirhost) != 0) {
412:         int ret = usbredirhost_write_guest_data(self->usbredirhost);
413:         if (ret < 0) {
414:             g_critical("%s: Failed to write to guest", __func__);
415:             goto end;
416:         }
417:     }
418: 
419:     // update the watch if needed
420:     update_watch(self);
421:     return G_SOURCE_CONTINUE;
422: 
423: end:
424:     g_main_loop_quit(self->main_loop);
425:     return G_SOURCE_REMOVE;
426: }
