459: static bool
460: can_claim_usb_device(libusb_device *dev, libusb_device_handle **handle)
461: {
462:     int ret = libusb_open(dev, handle);
463:     if (ret != 0) {
464:         g_debug("Failed to open device");
465:         return false;
466:     }
467: 
468:     /* Opening is not enough. We need to check if device can be claimed
469:      * for I/O operations */
470:     struct libusb_config_descriptor *config = NULL;
471:     ret = libusb_get_active_config_descriptor(dev, &config);
472:     if (ret != 0 || config == NULL) {
473:         g_debug("Failed to get active descriptor");
474:         goto fail;
475:     }
476: 
477: #if LIBUSBX_API_VERSION >= 0x01000102
478:     libusb_set_auto_detach_kernel_driver(*handle, 1);
479: #endif
480: 
481:     int i;
482:     for (i = 0; i < config->bNumInterfaces; i++) {
483:         int interface_num = config->interface[i].altsetting[0].bInterfaceNumber;
484: #if LIBUSBX_API_VERSION < 0x01000102
485:         ret = libusb_detach_kernel_driver(handle, interface_num);
486:         if (ret != 0 && ret != LIBUSB_ERROR_NOT_FOUND
487:             && ret != LIBUSB_ERROR_NOT_SUPPORTED) {
488:             g_error("failed to detach driver from interface %d: %s",
489:                     interface_num, libusb_error_name(ret));
490:             goto fail;
491:         }
492: #endif
493:         ret = libusb_claim_interface(*handle, interface_num);
494:         if (ret != 0) {
495:             g_debug("Could not claim interface");
496:             goto fail;
497:         }
498:         ret = libusb_release_interface(*handle, interface_num);
499:         if (ret != 0) {
500:             g_debug("Could not release interface");
501:             goto fail;
502:         }
503:     }
504: 
505:     libusb_free_config_descriptor(config);
506:     return true;
507: 
508: fail:
509:     libusb_free_config_descriptor(config);
510:     libusb_close(*handle);
511:     *handle = NULL;
512:     return false;
513: }
