515: static libusb_device_handle *
516: open_usb_device(redirect *self)
517: {
518:     struct libusb_device **devs;
519:     struct libusb_device_handle *dev_handle = NULL;
520:     size_t i, ndevices;
521: 
522:     ndevices = libusb_get_device_list(NULL, &devs);
523:     for (i = 0; i < ndevices; i++) {
524:         struct libusb_device_descriptor desc;
525:         if (libusb_get_device_descriptor(devs[i], &desc) != 0) {
526:             g_warning("Failed to get descriptor");
527:             continue;
528:         }
529: 
530:         if (self->by_bus &&
531:             (self->device.bus != libusb_get_bus_number(devs[i]) ||
532:              self->device.device_number != libusb_get_device_address(devs[i]))) {
533:              continue;
534:         }
535: 
536:         if (!self->by_bus &&
537:             (self->device.vendor != desc.idVendor ||
538:              self->device.product != desc.idProduct)) {
539:              continue;
540:         }
541: 
542:         if (can_claim_usb_device(devs[i], &dev_handle)) {
543:             break;
544:         }
545:     }
546: 
547:     libusb_free_device_list(devs, 1);
548:     return dev_handle;
549: }
