552: static gboolean
553: connection_incoming_cb(GSocketService    *service,
554:                        GSocketConnection *client_connection,
555:                        GObject           *source_object,
556:                        gpointer           user_data)
557: {
558:     redirect *self = (redirect *) user_data;
559: 
560:     // Check if there is already an active connection
561:     if (self->connection != NULL) {
562:         g_warning("Rejecting new connection: already connected to a client");
563:         return G_SOURCE_REMOVE;
564:     }
565: 
566:     self->connection = g_object_ref(client_connection);
567: 
568:     /* Add a GSource watch to handle polling for us and handle IO in the callback */
569:     GSocket *connection_socket = g_socket_connection_get_socket(self->connection);
570:     g_socket_set_keepalive(connection_socket, self->keepalive);
571:     create_watch(self);
572:     return G_SOURCE_REMOVE;
573: }
