575: int
576: main(int argc, char *argv[])
577: {
578:     GError *err = NULL;
579: 
580:     if (libusb_init(NULL)) {
581:         g_warning("Could not init libusb\n");
582:         goto err_init;
583:     }
584: 
585:     redirect *self = parse_opts(&argc, &argv);
586:     if (!self) {
587:         /* specific issues logged in parse_opts() */
588:         return 1;
589:     }
590: 
591: #if LIBUSBX_API_VERSION >= 0x01000107
592:     /* This was introduced in 1.0.23 */
593:     libusb_set_log_cb(NULL, debug_libusb_cb, LIBUSB_LOG_CB_GLOBAL);
594: #endif
595: 
596: #ifdef G_OS_WIN32
597:     /* WinUSB is the default by backwards compatibility so this is needed to
598:      * switch to USBDk backend. */
599: #   if LIBUSBX_API_VERSION >= 0x01000106
600:     libusb_set_option(NULL, LIBUSB_OPTION_USE_USBDK); 
601: #   endif
602: #endif
603: 
604: #ifdef G_OS_UNIX
605:     g_unix_signal_add(SIGINT, signal_handler, self);
606:     g_unix_signal_add(SIGHUP, signal_handler, self);
607:     g_unix_signal_add(SIGTERM, signal_handler, self);
608: #endif
609: 
610:     libusb_device_handle *device_handle = open_usb_device(self);
611:     if (!device_handle) {
612:         g_printerr("Failed to open device!\n");
613:         goto err_init;
614:     }
615: 
616:     /* As per doc below, we are not using hotplug so we must first call
617:      * libusb_open() and then we can start the event thread.
618:      *
619:      *      http://libusb.sourceforge.net/api-1.0/group__libusb__asyncio.html#eventthread
620:      *
621:      * The event thread is a must for Windows while on Unix we would ge okay
622:      * getting the fds and polling oursevelves. */
623:     g_atomic_int_set(&self->event_thread_run, TRUE);
624:     self->event_thread = g_thread_try_new("usbredirect-libusb-event-thread",
625:             thread_handle_libusb_events,
626:             self,
627:             &err);
628:     if (!self->event_thread) {
629:         g_warning("Error starting event thread: %s", err->message);
630:         libusb_close(device_handle);
631:         goto err_init;
632:     }
633: 
634:     self->usbredirhost = usbredirhost_open_full(NULL,
635:             device_handle,
636:             usbredir_log_cb,
637:             usbredir_read_cb,
638:             usbredir_write_cb,
639:             usbredir_write_flush_cb,
640:             usbredir_alloc_lock,
641:             usbredir_lock_lock,
642:             usbredir_unlock_lock,
643:             usbredir_free_lock,
644:             self,
645:             PACKAGE_STRING,
646:             self->verbosity,
647:             0);
648:     if (!self->usbredirhost) {
649:         g_warning("Error starting usbredirhost");
650:         goto err_init;
651:     }
652: 
653:     /* Only allow libusb logging if log verbosity is uredirparser_debug_data
654:      * (or higher), otherwise we disable it here while keeping usbredir's logs enable. */
655:     if  (self->verbosity < usbredirparser_debug_data)  {
656: #if LIBUSBX_API_VERSION >= 0x01000106
657:         int ret = libusb_set_option(NULL, LIBUSB_OPTION_LOG_LEVEL, LIBUSB_LOG_LEVEL_NONE);
658:         if (ret != LIBUSB_SUCCESS) {
659:             g_warning("error disabling libusb log level: %s", libusb_error_name(ret));
660:             goto end;
661:         }
662: #else
663:         libusb_set_debug(NULL, LIBUSB_LOG_LEVEL_NONE);
664: #endif
665:     }
666: 
667:     if (self->is_client) {
668:         /* Connect to a remote sever using usbredir to redirect the usb device */
669:         GSocketClient *client = g_socket_client_new();
670:         self->connection = g_socket_client_connect_to_host(client,
671:                 self->addr,
672:                 self->port, /* your port goes here */
673:                 NULL,
674:                 &err);
675:         g_object_unref(client);
676:         if (err != NULL) {
677:             g_warning("Failed to connect to the server: %s", err->message);
678:             goto end;
679:         }
680: 
681:         GSocket *connection_socket = g_socket_connection_get_socket(self->connection);
682:         g_socket_set_keepalive(connection_socket, self->keepalive);
683:         create_watch(self);
684:     } else {
685:         GSocketService *socket_service;
686: 
687:         socket_service = g_socket_service_new ();
688:         GInetAddress *iaddr = g_inet_address_new_from_string(self->addr);
689:         if (iaddr == NULL) {
690:             g_warning("Failed to parse IP: %s", self->addr);
691:             goto end;
692:         }
693: 
694:         GSocketAddress *saddr = g_inet_socket_address_new(iaddr, self->port);
695:         g_object_unref(iaddr);
696: 
697:         g_socket_listener_add_address(G_SOCKET_LISTENER (socket_service),
698:                 saddr,
699:                 G_SOCKET_TYPE_STREAM,
700:                 G_SOCKET_PROTOCOL_TCP,
701:                 NULL,
702:                 NULL,
703:                 &err);
704:         if (err != NULL) {
705:             g_warning("Failed to run as TCP server: %s", err->message);
706:             goto end;
707:         }
708: 
709:       g_signal_connect(socket_service,
710:               "incoming", G_CALLBACK (connection_incoming_cb),
711:               self);
712:     }
713: 
714:     self->main_loop = g_main_loop_new(NULL, FALSE);
715:     g_main_loop_run(self->main_loop);
716:     g_clear_pointer(&self->main_loop, g_main_loop_unref);
717: 
718:     g_atomic_int_set(&self->event_thread_run, FALSE);
719:     if (self->event_thread) {
720:         libusb_interrupt_event_handler(NULL);
721:         g_thread_join(self->event_thread);
722:         self->event_thread = NULL;
723:     }
724: 
725: end:
726:     g_clear_pointer(&self->usbredirhost, usbredirhost_close);
727:     g_clear_pointer(&self->addr, g_free);
728:     g_clear_object(&self->connection);
729:     g_free(self);
730: err_init:
731:     libusb_exit(NULL);
732: 
733:     if (err != NULL) {
734:         g_error_free(err);
735:         return 1;
736:     }
737: 
738:     return 0;
739: }

